from __future__ import annotations

from collections import Counter
from collections.abc import Callable
from typing import TYPE_CHECKING

import numpy as np

try:
    from .tour import Tour
except ImportError:
    from tour import Tour  # type: ignore

if TYPE_CHECKING:
    from .instance import TSPInstance

Crossover = Callable[[list[int], list[int], np.random.Generator], tuple[list[int], list[int]]]


def order_crossover(
    p1: list[int], p2: list[int], rng: np.random.Generator
) -> tuple[list[int], list[int]]:
    """Return two children generated by OX order crossover."""

    _validate_parents(p1, p2)
    n = len(p1)
    if n < 2:
        return p1.copy(), p2.copy()

    i, j = sorted(rng.choice(n, size=2, replace=False).astype(int).tolist())

    child1 = _make_ox_child(p1, p2, i, j)
    child2 = _make_ox_child(p2, p1, i, j)
    return child1, child2


def pmx_crossover(
    p1: list[int], p2: list[int], rng: np.random.Generator
) -> tuple[list[int], list[int]]:
    """Return two children generated by PMX crossover."""

    _validate_parents(p1, p2)
    n = len(p1)
    if n < 2:
        return p1.copy(), p2.copy()

    left, right = sorted(rng.choice(n, size=2, replace=False).astype(int).tolist())
    # Convert the inclusive right cut point into Python's half-open slice end.
    right += 1
    return (
        _make_pmx_child(p1, p2, left, right),
        _make_pmx_child(p2, p1, left, right),
    )


def edge_recombination_crossover(
    p1: list[int], p2: list[int], rng: np.random.Generator
) -> tuple[list[int], list[int]]:
    """Return two children generated by ERX edge recombination."""

    _validate_parents(p1, p2)
    n = len(p1)
    if n < 2:
        return p1.copy(), p2.copy()

    child1 = _make_erx_child(p1, p2, rng)
    child2 = _make_erx_child(p2, p1, rng)
    return child1, child2


def dpx_lite_crossover(
    p1: list[int], p2: list[int], rng: np.random.Generator
) -> tuple[list[int], list[int]]:
    """Return two children generated by a teaching DPX-lite operator.

    Merz and Freisleben's DPX preserves common parent edges and reconnects
    the remaining fragments. This lightweight version keeps that main idea
    but reconnects fragments with inherited parent edges instead of the full
    paper implementation.
    """

    _validate_parents(p1, p2)
    n = len(p1)
    if n < 2:
        return p1.copy(), p2.copy()

    child1 = _make_dpx_lite_child(p1, p2, rng)
    child2 = _make_dpx_lite_child(p2, p1, rng)
    return child1, child2


def dpx_crossover(
    p1: list[int],
    p2: list[int],
    rng: np.random.Generator,
    instance: "TSPInstance | None" = None,
) -> tuple[list[int], list[int]]:
    """Return two children generated by a distance-aware DPX-style operator.

    The paper's DPX keeps common parent edges, splits the tour into fragments,
    then greedily reconnects fragment endpoints with short new edges. When no
    instance is supplied, this falls back to the older DPX-lite operator.
    """

    _validate_parents(p1, p2)
    if instance is None:
        return dpx_lite_crossover(p1, p2, rng)
    child1 = _make_dpx_child(p1, p2, rng, instance.dist_matrix)
    child2 = _make_dpx_child(p2, p1, rng, instance.dist_matrix)
    return child1, child2


def gx_crossover(
    p1: list[int],
    p2: list[int],
    rng: np.random.Generator,
    instance: "TSPInstance | None" = None,
    c_rate: float = 1.0,
    n_rate: float = 0.25,
    i_rate: float = 0.5,
) -> tuple[list[int], list[int]]:
    """Return two children generated by the paper's GX idea.

    GX has four phases: copy common edges, insert short new edges, inherit short
    feasible parent edges, and greedily complete the remaining tour. The rates
    are fixed to a conservative paper-inspired default for this project.
    """

    _validate_parents(p1, p2)
    if instance is None:
        return edge_recombination_crossover(p1, p2, rng)
    child1 = _make_gx_child(p1, p2, rng, instance.dist_matrix, c_rate, n_rate, i_rate)
    child2 = _make_gx_child(p2, p1, rng, instance.dist_matrix, c_rate, n_rate, i_rate)
    return child1, child2


def apply_crossover(
    name: str,
    p1: list[int],
    p2: list[int],
    rng: np.random.Generator,
    instance: "TSPInstance | None" = None,
) -> tuple[list[int], list[int]]:
    """Dispatch crossover by name, passing the instance to distance-aware operators."""

    normalized = _normalize_crossover_name(name)
    if normalized == "dpx":
        return dpx_crossover(p1, p2, rng, instance)
    if normalized == "gx":
        return gx_crossover(p1, p2, rng, instance)
    return get_crossover(normalized)(p1, p2, rng)


def tour_edges(tour: list[int]) -> set[tuple[int, int]]:
    """Return the undirected edge set of a closed TSP tour."""

    _validate_permutation(tour)
    if len(tour) < 2:
        return set()
    return {
        _normalized_edge(city, tour[(idx + 1) % len(tour)])
        for idx, city in enumerate(tour)
    }


def canonical_tour_key(tour: list[int]) -> tuple[int, ...]:
    """Return a rotation/reversal-invariant key for an undirected TSP tour."""

    _validate_permutation(tour)
    if not tour:
        return ()
    min_city = min(tour)
    forward_start = tour.index(min_city)
    forward = tour[forward_start:] + tour[:forward_start]
    reversed_tour = list(reversed(tour))
    reverse_start = reversed_tour.index(min_city)
    backward = reversed_tour[reverse_start:] + reversed_tour[:reverse_start]
    return tuple(forward) if tuple(forward) <= tuple(backward) else tuple(backward)


def edge_set_key(tour: list[int]) -> frozenset[tuple[int, int]]:
    """Return a hashable undirected edge-set key for a closed tour."""

    return frozenset(tour_edges(tour))


def edge_recombination_metrics(
    child: list[int],
    p1: list[int],
    p2: list[int],
) -> dict[str, float | int]:
    """Measure how much of a child tour's edge structure came from its parents."""

    _validate_parents(p1, p2)
    if not _is_same_permutation(child, p1):
        raise ValueError("child must contain the same city set as parents")

    child_edges = tour_edges(child)
    p1_edges = tour_edges(p1)
    p2_edges = tour_edges(p2)
    parent_union = p1_edges | p2_edges
    common_edges = p1_edges & p2_edges
    inherited_edges = child_edges & parent_union
    common_preserved = child_edges & common_edges

    denominator = max(1, len(child_edges))
    common_denominator = max(1, len(common_edges))
    return {
        "edge_overlap_rate": len(inherited_edges) / denominator,
        "parent_edge_inheritance_rate": len(inherited_edges) / denominator,
        "common_edge_preservation_rate": len(common_preserved) / common_denominator,
        "foreign_edges_count": len(child_edges - parent_union),
        "child_parent_edge_distance": min(
            len(child_edges - p1_edges),
            len(child_edges - p2_edges),
        ),
    }


def get_crossover(
    name: str,
) -> Crossover:
    normalized = _normalize_crossover_name(name)
    if normalized in {"ox", "order", "order_crossover"}:
        return order_crossover
    if normalized in {"pmx", "partially_mapped", "partially_mapped_crossover"}:
        return pmx_crossover
    if normalized in {"erx", "edge", "edge_recombination"}:
        return edge_recombination_crossover
    if normalized in {"dpx", "dpx-lite", "dpx_lite", "distance_preserving"}:
        return dpx_lite_crossover
    if normalized in {"gx", "generic_greedy", "generic_greedy_recombination"}:
        return gx_crossover
    raise ValueError("crossover must be one of: ox, pmx, erx, dpx, gx")


def _normalize_crossover_name(name: str) -> str:
    normalized = name.strip().lower().replace("-", "_")
    if normalized in {"dpx_lite", "distance_preserving"}:
        return "dpx"
    if normalized in {"generic_greedy", "generic_greedy_recombination"}:
        return "gx"
    return normalized


def inversion_mutation(tour: list[int], rng: np.random.Generator) -> list[int]:
    """Return a copy with one randomly selected segment reversed."""

    _validate_permutation(tour)
    mutated = tour.copy()
    n = len(mutated)
    if n < 2:
        return mutated

    i, j = sorted(rng.choice(n, size=2, replace=False).astype(int).tolist())
    mutated[i : j + 1] = reversed(mutated[i : j + 1])
    return mutated


def swap_mutation(tour: list[int], rng: np.random.Generator) -> list[int]:
    """Return a copy with two randomly selected positions swapped."""

    _validate_permutation(tour)
    mutated = tour.copy()
    n = len(mutated)
    if n < 2:
        return mutated

    i, j = rng.choice(n, size=2, replace=False).astype(int).tolist()
    mutated[i], mutated[j] = mutated[j], mutated[i]
    return mutated


def tournament_selection(
    population: list[Tour],
    fitnesses: list[float],
    k: int = 3,
    rng: np.random.Generator | None = None,
) -> Tour:
    """Select the highest-fitness individual among k random candidates."""

    if rng is None:
        rng = np.random.default_rng()
    if len(population) != len(fitnesses):
        raise ValueError("population and fitnesses must have the same length")
    if not population:
        raise ValueError("population must not be empty")
    if not 1 <= k <= len(population):
        raise ValueError("k must be between 1 and len(population)")

    candidate_indices = rng.choice(len(population), size=k, replace=False)
    best_index = int(
        max(candidate_indices, key=lambda idx: (fitnesses[int(idx)], -int(idx)))
    )
    return population[best_index].copy()


def _make_ox_child(
    donor: list[int], filler: list[int], left: int, right: int
) -> list[int]:
    n = len(donor)
    child: list[int | None] = [None] * n
    child[left:right] = donor[left:right]
    used = set(donor[left:right])
    remaining = [city for city in filler if city not in used]
    fill_positions = list(range(0, left)) + list(range(right, n))

    for position, city in zip(fill_positions, remaining, strict=True):
        child[position] = city

    result = [int(city) for city in child if city is not None]
    if len(result) != n or not _is_same_permutation(result, donor):
        raise RuntimeError("order crossover produced an invalid child")
    return result


def _make_pmx_child(
    segment_parent: list[int], filler_parent: list[int], left: int, right: int
) -> list[int]:
    n = len(segment_parent)
    child: list[int | None] = [None] * n
    child[left:right] = segment_parent[left:right]
    filler_index = {city: idx for idx, city in enumerate(filler_parent)}

    for idx in range(left, right):
        city = filler_parent[idx]
        if city in child:
            continue

        position = idx
        while left <= position < right:
            mapped_city = segment_parent[position]
            position = filler_index[mapped_city]
        child[position] = city

    for idx in range(n):
        if child[idx] is None:
            child[idx] = filler_parent[idx]

    result = [int(city) for city in child if city is not None]
    if len(result) != n or not _is_same_permutation(result, segment_parent):
        raise RuntimeError("PMX produced an invalid child")
    return result


def _make_erx_child(
    p1: list[int], p2: list[int], rng: np.random.Generator
) -> list[int]:
    edge_map = _build_edge_map(p1, p2)
    unvisited = set(p1)
    current = int(rng.choice(p1))
    child: list[int] = []

    while unvisited:
        child.append(current)
        unvisited.remove(current)
        for neighbors in edge_map.values():
            neighbors.discard(current)

        if not unvisited:
            break

        candidates = [city for city in edge_map[current] if city in unvisited]
        if candidates:
            min_degree = min(len(edge_map[city]) for city in candidates)
            best = [city for city in candidates if len(edge_map[city]) == min_degree]
            current = int(rng.choice(best))
        else:
            current = int(rng.choice(list(unvisited)))

    if len(child) != len(p1) or not _is_same_permutation(child, p1):
        raise RuntimeError("ERX produced an invalid child")
    return child


def _make_dpx_lite_child(
    p1: list[int], p2: list[int], rng: np.random.Generator
) -> list[int]:
    common_edges = tour_edges(p1) & tour_edges(p2)
    if len(common_edges) == len(p1):
        return p1.copy()

    preserved_edges = _acyclic_common_edges(p1, common_edges, rng)
    fragments = _edge_fragments(p1, preserved_edges)
    child = _reconnect_fragments(fragments, tour_edges(p1) | tour_edges(p2), rng)
    if len(child) != len(p1) or not _is_same_permutation(child, p1):
        raise RuntimeError("DPX-lite produced an invalid child")
    return child


def _make_dpx_child(
    p1: list[int],
    p2: list[int],
    rng: np.random.Generator,
    dist_matrix: np.ndarray,
) -> list[int]:
    common_edges = tour_edges(p1) & tour_edges(p2)
    if len(common_edges) == len(p1):
        return p1.copy()

    preserved_edges = _acyclic_common_edges(p1, common_edges, rng)
    fragments = _edge_fragments(p1, preserved_edges)
    parent_edges = tour_edges(p1) | tour_edges(p2)
    child = _greedy_reconnect_fragments(
        fragments,
        parent_edges=parent_edges,
        dist_matrix=dist_matrix,
        rng=rng,
        avoid_parent_edges=True,
    )
    if len(child) != len(p1) or not _is_same_permutation(child, p1):
        raise RuntimeError("DPX produced an invalid child")
    return child


def _make_gx_child(
    p1: list[int],
    p2: list[int],
    rng: np.random.Generator,
    dist_matrix: np.ndarray,
    c_rate: float,
    n_rate: float,
    i_rate: float,
) -> list[int]:
    n = len(p1)
    parent_edges = tour_edges(p1) | tour_edges(p2)
    common_edges = tour_edges(p1) & tour_edges(p2)
    edges: set[tuple[int, int]] = set()
    cities = list(p1)

    for edge in sorted(common_edges):
        if rng.random() <= c_rate:
            _try_add_edge(edges, edge, cities)

    remaining = n - len(edges)
    _add_short_new_edges(
        edges,
        cities,
        parent_edges,
        dist_matrix,
        rng,
        target_count=int(remaining * n_rate),
    )

    remaining = n - len(edges)
    _add_inherited_edges(
        edges,
        p1,
        p2,
        cities,
        dist_matrix,
        rng,
        target_count=int(remaining * i_rate),
    )

    _greedy_complete_edges(edges, cities, dist_matrix, rng)
    child = _tour_from_edges(edges, cities)
    if len(child) != n or not _is_same_permutation(child, p1):
        raise RuntimeError("GX produced an invalid child")
    return child


def _acyclic_common_edges(
    cities: list[int],
    common_edges: set[tuple[int, int]],
    rng: np.random.Generator,
) -> set[tuple[int, int]]:
    parent = {city: city for city in cities}
    rank = {city: 0 for city in cities}
    degree = {city: 0 for city in cities}
    edges = list(common_edges)
    order = rng.permutation(len(edges)).astype(int).tolist() if edges else []
    preserved: set[tuple[int, int]] = set()

    def find(city: int) -> int:
        while parent[city] != city:
            parent[city] = parent[parent[city]]
            city = parent[city]
        return city

    def union(a: int, b: int) -> None:
        root_a = find(a)
        root_b = find(b)
        if root_a == root_b:
            return
        if rank[root_a] < rank[root_b]:
            parent[root_a] = root_b
        elif rank[root_a] > rank[root_b]:
            parent[root_b] = root_a
        else:
            parent[root_b] = root_a
            rank[root_a] += 1

    for idx in order:
        a, b = edges[idx]
        if degree[a] >= 2 or degree[b] >= 2:
            continue
        if find(a) == find(b):
            continue
        preserved.add((a, b))
        degree[a] += 1
        degree[b] += 1
        union(a, b)

    return preserved


def _edge_fragments(
    cities: list[int],
    edges: set[tuple[int, int]],
) -> list[list[int]]:
    adjacency = {city: set() for city in cities}
    for a, b in edges:
        adjacency[a].add(b)
        adjacency[b].add(a)

    unvisited = set(cities)
    fragments: list[list[int]] = []
    while unvisited:
        seed = min(unvisited)
        component = _component(seed, adjacency)
        endpoints = sorted(city for city in component if len(adjacency[city]) <= 1)
        start = endpoints[0] if endpoints else min(component)

        fragment: list[int] = []
        previous: int | None = None
        current: int | None = start
        while current is not None:
            fragment.append(current)
            unvisited.discard(current)
            candidates = sorted(
                city for city in adjacency[current] if city != previous
            )
            next_city = None
            for candidate in candidates:
                if candidate in unvisited:
                    next_city = candidate
                    break
            previous, current = current, next_city

        fragments.append(fragment)

    return fragments


def _component(seed: int, adjacency: dict[int, set[int]]) -> set[int]:
    stack = [seed]
    seen: set[int] = set()
    while stack:
        city = stack.pop()
        if city in seen:
            continue
        seen.add(city)
        stack.extend(neighbor for neighbor in adjacency[city] if neighbor not in seen)
    return seen


def _reconnect_fragments(
    fragments: list[list[int]],
    parent_edges: set[tuple[int, int]],
    rng: np.random.Generator,
) -> list[int]:
    remaining = [fragment.copy() for fragment in fragments]
    if not remaining:
        return []

    start_idx = int(rng.integers(0, len(remaining)))
    child = remaining.pop(start_idx)
    if len(child) > 1 and bool(rng.integers(0, 2)):
        child.reverse()

    while remaining:
        current_end = child[-1]
        first_city = child[0]
        scored: list[tuple[float, int, bool]] = []
        for idx, fragment in enumerate(remaining):
            for reverse in (False, True):
                candidate = list(reversed(fragment)) if reverse else fragment
                connector = _normalized_edge(current_end, candidate[0])
                inherited = connector in parent_edges
                closure = _normalized_edge(candidate[-1], first_city) in parent_edges
                score = (1.0 if inherited else 0.0) + (0.25 if closure else 0.0)
                scored.append((score, idx, reverse))

        best_score = max(score for score, _, _ in scored)
        best = [item for item in scored if item[0] == best_score]
        _, fragment_idx, reverse = best[int(rng.integers(0, len(best)))]
        fragment = remaining.pop(fragment_idx)
        if reverse:
            fragment = list(reversed(fragment))
        child.extend(fragment)

    return child


def _greedy_reconnect_fragments(
    fragments: list[list[int]],
    parent_edges: set[tuple[int, int]],
    dist_matrix: np.ndarray,
    rng: np.random.Generator,
    avoid_parent_edges: bool,
) -> list[int]:
    remaining = [fragment.copy() for fragment in fragments]
    if not remaining:
        return []

    start_idx = int(rng.integers(0, len(remaining)))
    child = remaining.pop(start_idx)
    if len(child) > 1 and bool(rng.integers(0, 2)):
        child.reverse()

    while remaining:
        current_end = child[-1]
        candidates: list[tuple[float, int, bool]] = []
        for idx, fragment in enumerate(remaining):
            for reverse in (False, True):
                oriented = list(reversed(fragment)) if reverse else fragment
                connector = _normalized_edge(current_end, oriented[0])
                if avoid_parent_edges and connector in parent_edges:
                    continue
                candidates.append((float(dist_matrix[current_end, oriented[0]]), idx, reverse))

        if not candidates:
            return _greedy_reconnect_fragments(
                [child] + remaining,
                parent_edges=parent_edges,
                dist_matrix=dist_matrix,
                rng=rng,
                avoid_parent_edges=False,
            )

        best_distance = min(distance for distance, _, _ in candidates)
        best = [item for item in candidates if item[0] == best_distance]
        _, fragment_idx, reverse = best[int(rng.integers(0, len(best)))]
        fragment = remaining.pop(fragment_idx)
        if reverse:
            fragment = list(reversed(fragment))
        child.extend(fragment)

    return child


def _add_short_new_edges(
    edges: set[tuple[int, int]],
    cities: list[int],
    parent_edges: set[tuple[int, int]],
    dist_matrix: np.ndarray,
    rng: np.random.Generator,
    target_count: int,
) -> None:
    attempts = 0
    max_attempts = max(20, target_count * 40)
    while target_count > 0 and attempts < max_attempts and len(edges) < len(cities):
        attempts += 1
        city = int(rng.choice(cities))
        nearest = np.argsort(dist_matrix[city]).astype(int).tolist()
        candidates = [other for other in nearest if other != city][:5]
        if len(candidates) > 1:
            rng.shuffle(candidates)
        for other in candidates:
            edge = _normalized_edge(city, int(other))
            if edge in parent_edges:
                continue
            if _try_add_edge(edges, edge, cities):
                target_count -= 1
                break


def _add_inherited_edges(
    edges: set[tuple[int, int]],
    p1: list[int],
    p2: list[int],
    cities: list[int],
    dist_matrix: np.ndarray,
    rng: np.random.Generator,
    target_count: int,
) -> None:
    parents = (p1, p2)
    attempts = 0
    max_attempts = max(20, target_count * 20)
    while target_count > 0 and attempts < max_attempts and len(edges) < len(cities):
        attempts += 1
        parent = parents[int(rng.integers(0, len(parents)))]
        feasible = [
            edge
            for edge in tour_edges(parent)
            if edge not in edges and _edge_is_feasible(edges, edge, cities)
        ]
        feasible.sort(key=lambda edge: dist_matrix[edge[0], edge[1]])
        if not feasible:
            continue
        candidates = feasible[:2]
        edge = candidates[int(rng.integers(0, len(candidates)))]
        if _try_add_edge(edges, edge, cities):
            target_count -= 1


def _greedy_complete_edges(
    edges: set[tuple[int, int]],
    cities: list[int],
    dist_matrix: np.ndarray,
    rng: np.random.Generator,
) -> None:
    n = len(cities)
    degree = {city: 0 for city in cities}
    parent = {city: city for city in cities}
    rank = {city: 0 for city in cities}

    def find(city: int) -> int:
        while parent[city] != city:
            parent[city] = parent[parent[city]]
            city = parent[city]
        return city

    def union(a: int, b: int) -> None:
        root_a = find(a)
        root_b = find(b)
        if root_a == root_b:
            return
        if rank[root_a] < rank[root_b]:
            parent[root_a] = root_b
        elif rank[root_a] > rank[root_b]:
            parent[root_b] = root_a
        else:
            parent[root_b] = root_a
            rank[root_a] += 1

    for a, b in edges:
        degree[a] += 1
        degree[b] += 1
        union(a, b)

    sorted_edges = sorted(
        (
            (
                float(dist_matrix[cities[i], cities[j]]),
                _normalized_edge(cities[i], cities[j]),
            )
            for i in range(n - 1)
            for j in range(i + 1, n)
        ),
        key=lambda item: item[0],
    )

    while len(edges) < len(cities):
        feasible: list[tuple[int, int]] = []
        for _, edge in sorted_edges:
            if edge in edges:
                continue
            a, b = edge
            if degree[a] >= 2 or degree[b] >= 2:
                continue
            same_component = find(a) == find(b)
            if len(edges) < n - 1:
                if same_component:
                    continue
            else:
                if not same_component:
                    continue
                if degree[a] != 1 or degree[b] != 1:
                    continue
            feasible.append(edge)
            if len(feasible) >= 2:
                break
        if not feasible:
            raise RuntimeError("could not greedily complete a feasible TSP tour")
        edge = feasible[int(rng.integers(0, len(feasible)))]
        edges.add(edge)
        a, b = edge
        degree[a] += 1
        degree[b] += 1
        if len(edges) < n:
            union(a, b)


def _try_add_edge(
    edges: set[tuple[int, int]],
    edge: tuple[int, int],
    cities: list[int],
) -> bool:
    if not _edge_is_feasible(edges, edge, cities):
        return False
    edges.add(edge)
    return True


def _edge_is_feasible(
    edges: set[tuple[int, int]],
    edge: tuple[int, int],
    cities: list[int],
) -> bool:
    a, b = edge
    n = len(cities)
    if a == b or edge in edges:
        return False
    degree = {city: 0 for city in cities}
    for x, y in edges:
        degree[x] += 1
        degree[y] += 1
    if degree[a] >= 2 or degree[b] >= 2:
        return False

    parent = _component_parents(cities, edges)
    same_component = _find(parent, a) == _find(parent, b)
    if len(edges) < n - 1:
        return not same_component

    if len(edges) == n - 1:
        if not same_component:
            return False
        degree[a] += 1
        degree[b] += 1
        return all(degree[city] == 2 for city in cities)

    return False


def _component_parents(
    cities: list[int],
    edges: set[tuple[int, int]],
) -> dict[int, int]:
    parent = {city: city for city in cities}
    for a, b in edges:
        root_a = _find(parent, a)
        root_b = _find(parent, b)
        if root_a != root_b:
            parent[root_b] = root_a
    return parent


def _find(parent: dict[int, int], city: int) -> int:
    while parent[city] != city:
        parent[city] = parent[parent[city]]
        city = parent[city]
    return city


def _tour_from_edges(edges: set[tuple[int, int]], cities: list[int]) -> list[int]:
    if len(edges) != len(cities):
        raise RuntimeError("edge set does not contain n tour edges")
    adjacency = {city: [] for city in cities}
    for a, b in edges:
        adjacency[a].append(b)
        adjacency[b].append(a)
    if any(len(neighbors) != 2 for neighbors in adjacency.values()):
        raise RuntimeError("edge set is not a Hamiltonian cycle")

    start = cities[0]
    tour = [start]
    previous: int | None = None
    current = start
    while True:
        choices = [city for city in adjacency[current] if city != previous]
        next_city = choices[0]
        if next_city == start:
            break
        if next_city in tour:
            raise RuntimeError("edge set contains a subtour")
        tour.append(next_city)
        previous, current = current, next_city

    if len(tour) != len(cities):
        raise RuntimeError("edge set does not visit every city")
    return tour


def _build_edge_map(p1: list[int], p2: list[int]) -> dict[int, set[int]]:
    edge_map = {city: set() for city in p1}
    for parent in (p1, p2):
        n = len(parent)
        for idx, city in enumerate(parent):
            edge_map[city].add(parent[(idx - 1) % n])
            edge_map[city].add(parent[(idx + 1) % n])
    return edge_map


def _validate_parents(p1: list[int], p2: list[int]) -> None:
    _validate_permutation(p1)
    _validate_permutation(p2)
    if not _is_same_permutation(p1, p2):
        raise ValueError("parents must contain the same city set")


def _validate_permutation(tour: list[int]) -> None:
    if len(set(tour)) != len(tour):
        raise ValueError("tour must not contain duplicate cities")


def _is_same_permutation(a: list[int], b: list[int]) -> bool:
    return len(a) == len(b) and set(a) == set(b)


def _normalized_edge(a: int, b: int) -> tuple[int, int]:
    return (a, b) if a < b else (b, a)


def _run_demo() -> None:
    rng = np.random.default_rng(0)
    p1 = rng.permutation(10).astype(int).tolist()
    p2 = rng.permutation(10).astype(int).tolist()
    child1, child2 = order_crossover(p1, p2, rng)
    pmx1, pmx2 = pmx_crossover(p1, p2, rng)
    erx1, erx2 = edge_recombination_crossover(p1, p2, rng)
    dpx1, dpx2 = dpx_lite_crossover(p1, p2, rng)

    print(f"p1: {p1}")
    print(f"p2: {p2}")
    print(f"child1 valid: {_is_same_permutation(child1, p1)}")
    print(f"child2 valid: {_is_same_permutation(child2, p1)}")
    print(f"pmx valid: {_is_same_permutation(pmx1, p1) and _is_same_permutation(pmx2, p1)}")
    print(f"erx valid: {_is_same_permutation(erx1, p1) and _is_same_permutation(erx2, p1)}")
    print(f"dpx-lite valid: {_is_same_permutation(dpx1, p1) and _is_same_permutation(dpx2, p1)}")
    print(f"dpx-lite metrics: {edge_recombination_metrics(dpx1, p1, p2)}")

    inversion = inversion_mutation(p1, rng)
    swap = swap_mutation(p1, rng)
    print(f"inversion valid: {_is_same_permutation(inversion, p1)}")
    print(f"swap valid: {_is_same_permutation(swap, p1)}")
    print(f"input unchanged: {len(p1) == 10 and _is_same_permutation(p1, list(range(10)))}")

    population = [Tour(rng.permutation(10).astype(int).tolist()) for _ in range(5)]
    fitnesses = [-100.0, -80.0, -60.0, -40.0, -20.0]
    counts: Counter[tuple[int, ...]] = Counter()
    for _ in range(100):
        selected = tournament_selection(population, fitnesses, k=3, rng=rng)
        counts[tuple(selected.cities)] += 1

    by_index = {
        idx: counts[tuple(individual.cities)] for idx, individual in enumerate(population)
    }
    print(f"tournament selection counts by population index: {by_index}")


if __name__ == "__main__":
    _run_demo()
